int rpmfiNext(rpmfi fi) /* <=== rpmfiNext */ 
{
    int next = -1;
    if (fi != NULL) {
	do {
	    next = fi->next(fi);
	} while (next == RPMERR_ITER_SKIP);

	if (next >= 0 && next < rpmfilesFC(fi->files)) {
	    fi->i = next;
	    fi->j = rpmfilesDI(fi->files, fi->i);
	} else {
	    fi->i = -1;
	    if (next >= 0) {
		next = -1;
	    }
	}
    }
    return next;
}

